-- Optional backup only. Worker auto-initializes the schema; no manual SQL is required for normal deployment.
CREATE TABLE IF NOT EXISTS meta (key TEXT PRIMARY KEY,value TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY,name TEXT NOT NULL,uuid TEXT NOT NULL UNIQUE,token TEXT NOT NULL UNIQUE,enabled INTEGER NOT NULL DEFAULT 1,traffic_limit INTEGER NOT NULL DEFAULT 0,traffic_used INTEGER NOT NULL DEFAULT 0,expires_at TEXT,port_mode TEXT NOT NULL DEFAULT 'auto',custom_ports TEXT NOT NULL DEFAULT '[]',path TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS nodes (id TEXT PRIMARY KEY,name TEXT NOT NULL,protocol TEXT NOT NULL,address TEXT NOT NULL,port INTEGER NOT NULL,tls INTEGER NOT NULL DEFAULT 1,host TEXT,path TEXT,sni TEXT,alpn TEXT,fingerprint TEXT,public_key TEXT,short_id TEXT,password TEXT,source_id TEXT,enabled INTEGER NOT NULL DEFAULT 1,latency INTEGER,last_ok INTEGER NOT NULL DEFAULT 0,last_test TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sources (id TEXT PRIMARY KEY,name TEXT NOT NULL,url TEXT NOT NULL UNIQUE,format TEXT NOT NULL DEFAULT 'auto',enabled INTEGER NOT NULL DEFAULT 1,priority INTEGER NOT NULL DEFAULT 100,last_sync TEXT,last_ok INTEGER NOT NULL DEFAULT 0,last_error TEXT,node_count INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS resources (id TEXT PRIMARY KEY,kind TEXT NOT NULL,value TEXT NOT NULL,label TEXT,source TEXT,enabled INTEGER NOT NULL DEFAULT 1,healthy INTEGER NOT NULL DEFAULT 0,latency INTEGER,last_test TEXT,failures INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL,UNIQUE(kind,value));
CREATE TABLE IF NOT EXISTS health (id TEXT PRIMARY KEY,kind TEXT NOT NULL,target TEXT NOT NULL,ok INTEGER NOT NULL,latency INTEGER,status INTEGER,error TEXT,tested_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS logs (id INTEGER PRIMARY KEY AUTOINCREMENT,level TEXT NOT NULL,action TEXT NOT NULL,detail TEXT,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_users_token ON users(token);CREATE INDEX IF NOT EXISTS idx_nodes_enabled ON nodes(enabled);CREATE INDEX IF NOT EXISTS idx_resources_kind ON resources(kind);CREATE INDEX IF NOT EXISTS idx_health_target ON health(target);